rdsample'=>'ejemplo','block keywordtext'=>'texto','block titleIcon'=>'Icono','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Un icono SVG. El código se limpia antes de mostrarse.','block keywordicon'=>'icono','block keywordsvg'=>'svg','block titleRow'=>'Fila','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Una fila de columnas. Permanece legible si el complemento llega a desactivarse.','block keywordrow'=>'fila','block keywordcolumns'=>'columnas','block titleShortcode (add-on)'=>'Shortcode (complemento)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Un código corto de un complemento escrito para el editor clásico Page Builder Sandwich, con la configuración que el complemento declaró.','block keywordshortcode'=>'código corto','block keywordadd-on'=>'complemento','block titleWidget area'=>'Área de widgets','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Muestra los widgets en una de las áreas de widgets del tema.','block keywordsidebar'=>'barra lateral','block keywordwidget area'=>'área de widgets','block titleWidget'=>'Widget','block descriptionShows one of the site\'s registered classic widgets.'=>'Muestra uno de los widgets clásicos registrados del sitio.','block keywordwidget'=>'widget']];